using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class ReportBendContact {public static string Main(){var mf=GameObject.Find("Ground_CR133 mountain driving surface").GetComponent<MeshFilter>();var mesh=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Track/ReportCleanup/forward-bend-continuous-grade.asset"));var v=mesh.vertices;int count=0;float max=0;for(int i=0;i<v.Length;i++){var p=mf.transform.TransformPoint(v[i]);float edge=Mathf.Min(p.x-1325,1375-p.x,p.z+293,-259-p.z);if(edge<=0||p.y<97||p.y>103)continue;float target=99.14f+.005f*(p.x-1348)+.009f*(p.z+275);float y=Mathf.Lerp(p.y,target,Mathf.SmoothStep(0,1,edge/7));max=Mathf.Max(max,Mathf.Abs(y-p.y));p.y=y;v[i]=mf.transform.InverseTransformPoint(p);count++;}mesh.vertices=v;mesh.RecalculateNormals();mesh.RecalculateBounds();string path="Assets/Track/ReportCleanup/forward-bend-contact-grade.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;mf.sharedMesh=mesh;mf.GetComponent<MeshCollider>().sharedMesh=null;mf.GetComponent<MeshCollider>().sharedMesh=mesh;Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(mf.gameObject.scene);EditorSceneManager.SaveScene(mf.gameObject.scene);AssetDatabase.SaveAssets();string result="The tight bend contained crossing pavement triangles on inconsistent grades (6cm contact jumps). Their shared local affine grade now removes those intersecting contact steps, fading outside the bend. Existing X/Z footprint and route preserved. Vertices="+count+" max local correction="+max;File.WriteAllText("Docs/ReportCleanup/BUG-015-contact-fix.txt",result);return result;}}


